    /// `idx < buf_count`.
    fn buf_ptr(&self, idx: u32) -> *mut u8 {
        // SAFETY: idx < buf_count, so the offset stays inside
        // the buffer array validated at init/attach.
        unsafe { self.bufs.add(idx as usize * self.buf_size as usize) }
    }
