            return Err(Error::BadLayoutVersion);
        }
        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
            return Err(Error::BadCacheLine);
        }
        // Snapshot geometry once. Per-op paths never re-read.
        let buf_size = header.buf_size.load(Ordering::Relaxed);
        let buf_count = header.buf_count.load(Ordering::Relaxed);
        validate_pool_geometry(buf_size, buf_count)?;
        if (len as u64) < pool_region_size(buf_size, buf_count) {
            return Err(Error::TooSmall);
        }
        // SAFETY: in bounds, len >= header + buffers.
        let bufs = unsafe { region.add(size_of::<PoolHeader>()) };
        Ok(Pool {
            header,
            bufs,
            buf_size,
            buf_count,
            _region: PhantomData,
        })
    }

    /// Pop the first free buffer off the free-stack as an
    /// owned [`BufSlot`], or [`Exhausted`].
    ///
    /// - `&mut self` is the in-process single-popper token, and
    ///   cross-process, at most one attached handle allocates
    ///   (see [`Pool::attach`]). The guard does **not** borrow
    ///   the pool. Any number of allocated buffers may be
    ///   live at once. Per-buffer exclusivity comes from the
    ///   free-stack protocol (each pop yields a distinct
    ///   index), not the borrow checker.
    /// - Validated pop: the head and its next-link live in
    ///   peer-writable memory, so both are bounds-checked.
    ///   Corruption degrades to `Exhausted` (mirroring the
    ///   ring's fail-toward-`Full` occupancy check), never to
    ///   an out-of-bounds buffer.
    /// - A racing free moves the head and the CAS retries.
    ///   With a single popper an in-flight head node cannot be
    ///   removed underneath us, so there is no ABA hazard.

content.content:
470	    /// Snapshot of the pool's buffer size, the length a
471	    /// `BufSlot<[u8]>` derefs to.
472	    buf_size: u32,
473	    /// This buffer's index (the value free pushes).
474	    idx: u32,
475	    /// The guard acts as a `&mut T` into the region.
476	    _slot: PhantomData<&'p mut T>,
477	}
478	
479	// SAFETY: the guard owns its buffer exclusively (the pop
480	// removed it from every shared structure). Free's CAS is the
481	// only shared-state touch and is properly ordered.
482	unsafe impl<T: ?Sized + Send> Send for BufSlot<'_, T> {}
483	
484	impl<T> Deref for BufSlot<'_, T> {
485	    type Target = T;
486	    /// Read access to the buffer as a `T`.
487	    fn deref(&self) -> &T {
488	        // SAFETY: buf is in-bounds and cache-line aligned
489	        // (validated geometry), any byte pattern is a valid T
490	        // (FromBytes bound at alloc), and the pop gave this
491	        // guard sole ownership until free.
492	        unsafe { &*(self.buf as *const T) }
493	    }
494	}
495	
496	impl<T> DerefMut for BufSlot<'_, T> {
497	    /// Write access to the buffer as a `T`.
498	    fn deref_mut(&mut self) -> &mut T {
499	        // SAFETY: as in deref, and &mut self gives exclusivity of
500	        // the minted reference.
501	        unsafe { &mut *(self.buf as *mut T) }
502	    }
503	}
504	
505	impl Deref for BufSlot<'_, [u8]> {
506	    type Target = [u8];
507	    /// Read access to the whole buffer as bytes.
508	    fn deref(&self) -> &[u8] {
509	        // SAFETY: buf is the base of a buffer of buf_size bytes
510	        // inside the validated region, any byte pattern is a
511	        // valid u8, and the pop gave this guard sole ownership
512	        // until free.
513	        unsafe { core::slice::from_raw_parts(self.buf, self.buf_size as usize) }
514	    }
515	}
516	
517	impl DerefMut for BufSlot<'_, [u8]> {
518	    /// Write access to the whole buffer as bytes.
519	    fn deref_mut(&mut self) -> &mut [u8] {
520	        // SAFETY: as in deref, and &mut self gives exclusivity of
521	        // the minted slice.
522	        unsafe { core::slice::from_raw_parts_mut(self.buf, self.buf_size as usize) }
523	    }
524	}
525	
526	impl<T: ?Sized> BufSlot<'_, T> {
527	    /// The owning pool's header address, matched against a
528	    /// registry entry's [`PoolResolver::header_ptr`] by
529	    /// [`PoolRegistry::into_desc`](crate::PoolRegistry::into_desc).
530	    pub(crate) fn header_ptr(&self) -> *const PoolHeader {
531	        self.header
532	    }
533	
534	    /// This buffer's index (the descriptor payload).
535	    pub(crate) fn idx(&self) -> u32 {
536	        self.idx
537	    }
538	
539	    /// The buffer's base as the pool's own raw pointer, for a
540	    /// holder that lays its own structure over the buffer and
541	    /// shares it between threads, so every access derives from
542	    /// one pointer rather than from a `&mut` borrow of the guard.
543	    pub(crate) fn as_mut_ptr(&self) -> *mut u8 {
544	        self.buf
545	    }
546	
547	    /// Push the buffer back onto the pool's free-stack.
548	    ///
549	    /// - Any holder may free: this is the free-stack's MPSC
550	    ///   push side. Only allocation is single-popper.
551	    /// - The CAS retries only when another free (or the
552	    ///   allocator's pop) moves the head first.
553	    pub fn free(self) {
554	        // The buffer's first word becomes its next-link again.
555	        let link = self.buf as *const AtomicU32;
556	        // SAFETY: buf is in-bounds and 4-aligned (cache-line
557	        // aligned base). The guard still owns the buffer, and
558	        // all peers access this word as an atomic.
559	        let link = unsafe { &*link };
560	        loop {
561	            let head = self.header.first_free_idx.load(Ordering::Relaxed);
562	            link.store(head, Ordering::Relaxed);
563	            // Release pairs with alloc's Acquire loads: the
564	            // popper that sees idx also sees the link store
565	            // above (and this holder's last buffer writes).
566	            if self
567	                .header
568	                .first_free_idx
569	                .compare_exchange(head, self.idx, Ordering::Release, Ordering::Relaxed)
570	                .is_ok()
571	            {
572	                return;
573	            }
574	        }
575	    }
576	}
