578	/// Validate a region base pointer and cast it to the
579	/// `PoolHeader` it must start with, shared by
580	/// [`Pool::init`] / [`Pool::attach`].
581	///
582	/// - Checks alignment and room for the header itself. The
583	///   full-geometry length check stays with the caller (init
584	///   knows the geometry from parameters, attach only after
585	///   reading the header).
586	fn pool_header_ptr(base: *mut u8, len: usize) -> Result<*const PoolHeader, Error> {
587	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
588	        return Err(Error::Misaligned);
589	    }
590	    if len < size_of::<PoolHeader>() {
591	        return Err(Error::TooSmall);
592	    }
593	    Ok(base as *const PoolHeader)
594	}
595	
596	/// Bytes needed for a pool region with the given geometry,
597	/// computed in u64 for the same 32-bit wrap reason as the
598	/// ring's `region_size`.
599	fn pool_region_size(buf_size: u32, buf_count: u32) -> u64 {
600	    size_of::<PoolHeader>() as u64 + buf_size as u64 * buf_count as u64
601	}
602	
603	/// Shared geometry checks for [`Pool::init`] /
604	/// [`Pool::attach`].
605	///
606	/// - No power-of-two constraint: the free-stack never masks
607	///   an index.
608	fn validate_pool_geometry(buf_size: u32, buf_count: u32) -> Result<(), Error> {
609	    if buf_size == 0 || !(buf_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
610	        return Err(Error::BadBufSize);
611	    }
612	    if buf_count == 0 || buf_count == NIL {
613	        return Err(Error::BadBufCount);
614	    }
615	    Ok(())
616	}
