939	                            Err(Exhausted) => std::hint::spin_loop(),
940	                        }
941	                    }
942	                }
943	            });
944	            s.spawn(move || {
945	                for i in 0..COUNT {
946	                    let b = rx.recv().unwrap();
947	                    assert_eq!(b.seq, i);
948	                    assert_eq!(b.val, i * 3);
