unsafe impl<const N: usize> Send for Pool<'_, N> {}

impl<'a, const N: usize> Pool<'a, N> {
    /// Initialize a fresh region and return the pool over it, with every buffer on its
    /// stack.
    ///
    /// - `stacks`: `(buf_size, buf_count)` per stack, sizes [`CACHE_LINE_SIZE`] multiples in
    }

    /// Allocations, per stack, that wanted the stack and found it empty, since this
    /// handle was made.
    ///
    /// - A count that keeps rising says the stack wants more buffers.
    pub fn misses(&self) -> [u64; N] {
        self.misses
    }
    /// Read access to the buffer as a `T`.
    fn deref(&self) -> &T {
        // SAFETY: buf is in-bounds and cache-line aligned (validated geometry), T fits the stack
        // (alloc picked a stack whose buffers hold size_of::<T>() bytes), any byte pattern is a valid T
        // (FromBytes bound at alloc), and the pop gave this guard sole ownership until free.
        unsafe { &*(self.buf as *const T) }
    }
}

