1	//! Descriptors and the per-process pool registry, the
2	//! resolution half of the messaging layer: a [`Desc`] names a
3	//! buffer as `(pool id, buffer index)` so it can ride any
4	//! queue as an ordinary POD message, and the [`PoolRegistry`]
5	//! turns descriptors back into owned guards (see the design
6	//! doc's "Descriptor and registry design (0.7.0)").
7	//!
8	//! - [`PoolRegistry::into_desc`] (safe) consumes a guard into
9	//!   a descriptor, and ownership travels on in the descriptor.
10	//! - [`PoolRegistry::resolve`] (unsafe) validates a received
11	//!   descriptor and mints the guard back, and `unsafe` covers
12	//!   only what validation cannot check, ownership
13	//!   uniqueness.
14	//! - Fixed capacity, no allocation, no unregister: pool ids
15	//!   are registry slot indices and never dangle.
16	
17	use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
18	
19	use crate::pool::PoolResolver;
20	use crate::{BufSlot, type_fits};
21	
22	/// A buffer's travel form: names its pool and buffer index so
23	/// any queue can carry it as an ordinary message.
24	///
25	/// - Plain data on purpose: `FromBytes` means a receiver
26	///   mints one from shared bytes anyway, so ownership
27	///   discipline lives in [`PoolRegistry::resolve`]'s
28	///   contract, not in this type.
29	/// - Fields are raw `u32`s (not [`PoolId`]) because the wire
30	///   form is untrusted by definition, and validation happens at
31	///   resolve.
32	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, Clone, Copy, PartialEq, Eq)]
33	#[repr(C)]
34	pub struct Desc {
35	    /// The registry slot of the buffer's pool.
36	    pub pool_id: u32,
37	    /// The buffer's index within that pool.
38	    pub buf_idx: u32,
39	}
40	
41	/// A registered pool's identity within one process's
42	/// [`PoolRegistry`], the value [`register`](PoolRegistry::register)
43	/// returns.
44	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
45	pub struct PoolId(u32);
46	
47	impl PoolId {
48	    /// The raw id (a registry slot index).
49	    pub fn as_u32(self) -> u32 {
50	        self.0
51	    }
52	}
53	
54	/// Errors from [`PoolRegistry`] operations.
55	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
56	pub enum RegistryError {
57	    /// `register`: the fixed-capacity table is full.
58	    Full,
59	    /// The pool id names no registered pool.
60	    UnknownPoolId,
61	    /// `into_desc`: the guard's pool is not the id's entry.
62	    WrongPool,
63	    /// `resolve`: buffer index out of range for the pool.
64	    BadIndex,
65	    /// `resolve`: `T`'s geometry does not fit the pool's
66	    /// buffers. An `Err`, not the `alloc`-style panic: the
67	    /// descriptor selects which pool gets compared, and
68	    /// untrusted input must not select a panic.
69	    BadType,
70	}
71	
72	/// Per-process table mapping pool ids to this process's
73	/// [`PoolResolver`] view of each pool.
74	///
75	/// - Fixed capacity `N` (const generic): no_std, zero
76	///   allocation.
77	/// - `register` assigns the next slot index as the pool's id, and
78	///   there is no unregister, so ids never dangle.
79	/// - Registration (`&mut self`) is setup-phase, and `into_desc` /
80	///   `resolve` take `&self`, so one registry is shared by
81	///   reference across threads.
82	pub struct PoolRegistry<'a, const N: usize> {
83	    /// Registered views, dense from slot 0.
84	    resolvers: [Option<PoolResolver<'a>>; N],
85	    /// Number of registered pools (next id to assign).
86	    len: usize,
87	}
88	
89	impl<'a, const N: usize> PoolRegistry<'a, N> {
90	    /// An empty registry.
91	    pub const fn new() -> Self {
92	        Self {
93	            resolvers: [None; N],
94	            len: 0,
95	        }
96	    }
97	
98	    /// Register a pool's resolver view, and returns the assigned
99	    /// [`PoolId`] (the next slot index), or
100	    /// [`RegistryError::Full`].
101	    pub fn register(&mut self, resolver: PoolResolver<'a>) -> Result<PoolId, RegistryError> {
102	        if self.len == N {
103	            return Err(RegistryError::Full);
104	        }
105	        let id = self.len as u32;
106	        self.resolvers[self.len] = Some(resolver);
107	        self.len += 1;
108	        Ok(PoolId(id))
109	    }
110	
111	    /// Consume a guard into its descriptor, and ownership travels
112	    /// on in the [`Desc`] (the usage model's "in-flight"
113	    /// state).
114	    ///
115	    /// - O(1): checks the guard's pool identity (header
116	    ///   address) against the id's entry, catching id/pool
117	    ///   mispairing.
118	    /// - The error side hands the guard back, so a miss
119	    ///   cannot leak the buffer.
120	    pub fn into_desc<T: ?Sized>(
121	        &self,
122	        pool_id: PoolId,
123	        slot: BufSlot<'a, T>,
124	    ) -> Result<Desc, (BufSlot<'a, T>, RegistryError)> {
125	        let Some(resolver) = self.get(pool_id.0) else {
126	            return Err((slot, RegistryError::UnknownPoolId));
127	        };
128	        if !core::ptr::eq(resolver.header_ptr(), slot.header_ptr()) {
129	            return Err((slot, RegistryError::WrongPool));
130	        }
131	        Ok(Desc {
132	            pool_id: pool_id.0,
133	            buf_idx: slot.idx(),
134	        })
135	    }
136	
137	    /// Validate a received descriptor and mint its owned
138	    /// guard.
139	    ///
140	    /// Every validation failure is an `Err`, never a panic:
141	    /// unknown pool id, index out of range, `T` geometry
142	    /// mismatch (see [`RegistryError::BadType`] for why this
143	    /// differs from `alloc`).
144	    ///
145	    /// # Safety
146	    ///
147	    /// Validation cannot check ownership, and the caller promises:
148	    ///
149	    /// - `desc` came from [`into_desc`](Self::into_desc) (or
150	    ///   an equivalent consumed guard). It is not invented.
151	    /// - It arrived over a channel establishing happens-before
152	    ///   with the sender's writes (a ring commit -> reserve
153	    ///   qualifies).
154	    /// - It is resolved exactly once. A second resolve mints
155	    ///   a second guard aliasing the same `&mut T`.
156	    pub unsafe fn resolve<T>(&self, desc: Desc) -> Result<BufSlot<'a, T>, RegistryError>
157	    where
158	        T: FromBytes + IntoBytes + KnownLayout,
159	    {
160	        let Some(resolver) = self.get(desc.pool_id) else {
161	            return Err(RegistryError::UnknownPoolId);
162	        };
163	        if desc.buf_idx >= resolver.buf_count() {
164	            return Err(RegistryError::BadIndex);
165	        }
166	        if !type_fits::<T>(resolver.buf_size()) {
167	            return Err(RegistryError::BadType);
168	        }
169	        // SAFETY: index and T geometry validated above.
170	        // Ownership uniqueness and ordering are the caller's
171	        // contract (this fn's # Safety).
172	        Ok(unsafe { resolver.slot_from_idx(desc.buf_idx) })
173	    }
174	
175	    /// Number of registered pools.
176	    pub fn len(&self) -> usize {
177	        self.len
178	    }
179	
180	    /// True when no pool is registered.
181	    pub fn is_empty(&self) -> bool {
182	        self.len == 0
183	    }
184	
185	    /// The resolver registered under raw id `id`, if any.
186	    fn get(&self, id: u32) -> Option<&PoolResolver<'a>> {
187	        self.resolvers.get(id as usize)?.as_ref()
188	    }
189	}
190	
191	impl<const N: usize> Default for PoolRegistry<'_, N> {
192	    /// Same as [`PoolRegistry::new`].
193	    fn default() -> Self {
194	        Self::new()
195	    }
196	}
197	
198	#[cfg(test)]
199	mod tests {
200	    use super::*;
201	    use crate::{CACHE_LINE_SIZE, Exhausted, Pool, PoolHeader};
202	    use core::mem::size_of;
203	
204	    /// Test message: one word carrying a sequence number.
205	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
206	    #[repr(C)]
207	    struct Msg {
208	        seq: u64,
209	    }
210	
211	    /// One-line buffers / slots for every test.
212	    const LINE: u32 = CACHE_LINE_SIZE as u32;
213	
214	    /// Pool region: header + 4 one-line buffers.
215	    const POOL_BYTES: usize = size_of::<PoolHeader>() + 4 * CACHE_LINE_SIZE;
216	
217	    /// Ring region: header (4 lines) + 4 one-line slots.
218	    const RING_BYTES: usize = 8 * CACHE_LINE_SIZE;
219	
220	    /// Cache-line-aligned backing store for pool/ring regions.
221	    #[repr(C, align(64))]
222	    struct Region<const B: usize>([u8; B]);
223	
224	    #[test]
225	    fn desc_round_trip() {
226	        let mut pr = Region::<POOL_BYTES>([0; POOL_BYTES]);
227	        let mut pool = Pool::init(&mut pr.0, LINE, 4).unwrap();
228	        let mut reg = PoolRegistry::<2>::new();
229	        assert!(reg.is_empty());
230	        let id = reg.register(pool.resolver()).unwrap();
231	        assert_eq!(id.as_u32(), 0);
232	        assert_eq!(reg.len(), 1);
233	
234	        let mut slot = pool.alloc::<Msg>().unwrap();
235	        slot.seq = 42;
236	        let desc = reg.into_desc(id, slot).map_err(|(_, e)| e).unwrap();
237	        assert_eq!(
238	            desc,
239	            Desc {
240	                pool_id: 0,
241	                buf_idx: 0
242	            }
243	        );
244	
245	        // SAFETY: desc came from into_desc on this thread and
246	        // is resolved exactly once.
247	        let got = unsafe { reg.resolve::<Msg>(desc) }.unwrap();
248	        assert_eq!(got.seq, 42);
249	        got.free();
250	
251	        // The freed buffer is back on the free-stack: all 4
252	        // allocate again, then exhaustion.
253	        let slots: [_; 4] = core::array::from_fn(|_| pool.alloc::<Msg>().unwrap());
254	        assert_eq!(pool.alloc::<Msg>().err().unwrap(), Exhausted);
255	        slots.into_iter().for_each(BufSlot::free);
256	    }
257	
258	    #[test]
259	    fn into_desc_checks_pool_identity() {
260	        let mut ra = Region::<POOL_BYTES>([0; POOL_BYTES]);
261	        let mut rb = Region::<POOL_BYTES>([0; POOL_BYTES]);
262	        let mut pool_a = Pool::init(&mut ra.0, LINE, 4).unwrap();
263	        let pool_b = Pool::init(&mut rb.0, LINE, 4).unwrap();
264	        let mut reg = PoolRegistry::<2>::new();
265	        let id_a = reg.register(pool_a.resolver()).unwrap();
266	        let id_b = reg.register(pool_b.resolver()).unwrap();
267	
268	        // Mispaired id: rejected, and the guard comes back
269	        // usable, no leak.
270	        let slot = pool_a.alloc::<Msg>().unwrap();
271	        let (slot, err) = reg.into_desc(id_b, slot).unwrap_err();
272	        assert_eq!(err, RegistryError::WrongPool);
273	        let desc = reg.into_desc(id_a, slot).map_err(|(_, e)| e).unwrap();
274	        // SAFETY: desc came from into_desc, resolved once.
275	        unsafe { reg.resolve::<Msg>(desc) }.unwrap().free();
276	    }
277	
278	    #[test]
279	    fn into_desc_unknown_pool_id() {
280	        let mut ra = Region::<POOL_BYTES>([0; POOL_BYTES]);
281	        let mut rb = Region::<POOL_BYTES>([0; POOL_BYTES]);
282	        let mut pool_a = Pool::init(&mut ra.0, LINE, 4).unwrap();
283	        let pool_b = Pool::init(&mut rb.0, LINE, 4).unwrap();
284	        // An id minted by a bigger registry has no entry in a
285	        // smaller one.
286	        let mut big = PoolRegistry::<2>::new();
287	        big.register(pool_a.resolver()).unwrap();
288	        let id_b = big.register(pool_b.resolver()).unwrap();
289	        let mut small = PoolRegistry::<1>::new();
290	        small.register(pool_a.resolver()).unwrap();
291	
292	        let slot = pool_a.alloc::<Msg>().unwrap();
293	        let (slot, err) = small.into_desc(id_b, slot).unwrap_err();
294	        assert_eq!(err, RegistryError::UnknownPoolId);
295	        slot.free();
296	    }
297	
298	    #[test]
299	    fn resolve_rejects_hostile_descs() {
300	        let mut pr = Region::<POOL_BYTES>([0; POOL_BYTES]);
301	        let pool = Pool::init(&mut pr.0, LINE, 4).unwrap();
302	        let mut reg = PoolRegistry::<1>::new();
303	        reg.register(pool.resolver()).unwrap();
304	
305	        // SAFETY: every resolve here must fail validation and
306	        // mint nothing, and no ownership is claimed.
307	        unsafe {
308	            let bad_pool = Desc {
309	                pool_id: 7,
310	                buf_idx: 0,
311	            };
312	            assert_eq!(
313	                reg.resolve::<Msg>(bad_pool).err().unwrap(),
314	                RegistryError::UnknownPoolId
315	            );
316	            let bad_idx = Desc {
317	                pool_id: 0,
318	                buf_idx: 4,
319	            };
320	            assert_eq!(
321	                reg.resolve::<Msg>(bad_idx).err().unwrap(),
322	                RegistryError::BadIndex
323	            );
324	            let ok_target = Desc {
325	                pool_id: 0,
326	                buf_idx: 0,
327	            };
328	            // T bigger than the pool's one-line buffers.
329	            assert_eq!(
330	                reg.resolve::<[u8; 2 * CACHE_LINE_SIZE]>(ok_target)
331	                    .err()
332	                    .unwrap(),
333	                RegistryError::BadType
334	            );
335	        }
336	    }
337	
338	    #[test]
339	    fn register_full() {
340	        let mut pr = Region::<POOL_BYTES>([0; POOL_BYTES]);
341	        let pool = Pool::init(&mut pr.0, LINE, 4).unwrap();
342	        let mut reg = PoolRegistry::<1>::new();
343	        reg.register(pool.resolver()).unwrap();
344	        assert_eq!(
345	            reg.register(pool.resolver()).unwrap_err(),
346	            RegistryError::Full
347	        );
348	    }
349	
350	    /// The composed protocol: descriptors carry pool-buffer
351	    /// ownership through the SPSC ring, producer thread to
352	    /// consumer thread, buffers recycling under pressure
353	    /// (COUNT >> buf_count).
354	    #[test]
355	    fn desc_over_ring_cross_thread() {
356	        const COUNT: u64 = if cfg!(miri) { 200 } else { 10_000 };
357	        let mut pr = Region::<POOL_BYTES>([0; POOL_BYTES]);
358	        let mut rr = Region::<RING_BYTES>([0; RING_BYTES]);
359	        let mut pool = Pool::init(&mut pr.0, LINE, 4).unwrap();
360	        let mut reg = PoolRegistry::<1>::new();
361	        let id = reg.register(pool.resolver()).unwrap();
362	        let reg = &reg;
363	        let (mut producer, mut consumer) = crate::spsc::v2::Ring::init(&mut rr.0, LINE, 4)
364	            .unwrap()
365	            .split();
366	
367	        std::thread::scope(|s| {
368	            s.spawn(move || {
369	                for i in 0..COUNT {
370	                    let mut buf = loop {
371	                        match pool.alloc::<Msg>() {
372	                            Ok(buf) => break buf,
373	                            Err(Exhausted) => std::hint::spin_loop(),
374	                        }
375	                    };
376	                    buf.seq = i;
377	                    let desc = reg.into_desc(id, buf).map_err(|(_, e)| e).unwrap();
378	                    let mut slot = producer
379	                        .reserve_slot_with::<Desc>(crate::policy::spin)
380	                        .unwrap();
381	                    *slot = desc;
382	                    slot.commit();
383	                }
384	            });
385	            s.spawn(move || {
386	                for i in 0..COUNT {
387	                    let desc = {
388	                        let slot = consumer
389	                            .reserve_slot_with::<Desc>(crate::policy::spin)
390	                            .unwrap();
391	                        let desc = *slot;
392	                        slot.release();
393	                        desc
394	                    };
395	                    // SAFETY: the desc was consumed into the
396	                    // ring by the producer and read after the
397	                    // commit -> reserve handoff (happens-
398	                    // before), and each is resolved exactly once.
399	                    let msg = unsafe { reg.resolve::<Msg>(desc) }.unwrap();
400	                    assert_eq!(msg.seq, i);
401	                    msg.free();
402	                }
403	            });
404	        });
405	    }
406	}
